// Lambda function: user-profile-service/index.js
const AWS = require('aws-sdk');
const dynamodb = new AWS.DynamoDB.DocumentClient();

// Unicode normalization utility
function normalizeUsername(input) {
  // Strip control characters but preserve unicode letters
  const cleaned = input.replace(/[\x00-\x1F\x7F]/g, '');
  return cleaned;
}

// Check if username matches admin pattern
function isAdminUser(username) {
  const normalized = username.normalize('NFC');
  // Block direct admin access attempts
  if (normalized.toLowerCase() === 'admin') {
    return true;
  }
  return false;
}

// Authorization check using NFKC normalization
function checkAuthorization(requestedUser, authenticatedUser) {
  // Normalize both to NFKC for comparison
  const reqNormalized = requestedUser.normalize('NFKC').toLowerCase();
  const authNormalized = authenticatedUser.normalize('NFKC').toLowerCase();
  return reqNormalized === authNormalized;
}

exports.handler = async (event) => {
  try {
    const body = JSON.parse(event.body);
    const requestedUsername = body.username;
    const action = body.action || 'read';

    // Extract authenticated identity from request context
    const authContext = event.requestContext?.authorizer || {};
    const authenticatedUser = authContext.principalId || 'anonymous';

    if (!requestedUsername) {
      return { statusCode: 400, body: JSON.stringify({ error: 'username required' }) };
    }

    // Sanitize input
    const sanitizedUsername = normalizeUsername(requestedUsername);

    // Admin check uses NFC normalization
    if (isAdminUser(sanitizedUsername)) {
      // Only allow if authenticated as admin
      if (authenticatedUser !== 'admin') {
        return { statusCode: 403, body: JSON.stringify({ error: 'admin access denied' }) };
      }
    }

    // VULNERABILITY: Authorization bypass via Unicode normalization mismatch
    // isAdminUser uses NFC, but the DynamoDB lookup uses the raw sanitized input
    // An attacker can use characters that:
    //   - Don't normalize to 'admin' under NFC (bypasses isAdminUser check)
    //   - DO normalize to 'admin' under NFKC (matches in DynamoDB GSI)
    // Example: 'ⓐdmin' (U+24D0 = circled latin small letter a)
    //   NFC('ⓐdmin') = 'ⓐdmin' (unchanged, not 'admin') -> bypasses check
    //   NFKC('ⓐdmin') = 'admin' -> matches admin record in DB

    // Lookup uses NFKC-normalized index
    const lookupKey = sanitizedUsername.normalize('NFKC').toLowerCase();

    if (action === 'read') {
      const result = await dynamodb.get({
        TableName: process.env.USERS_TABLE || 'user-profiles',
        Key: { username_normalized: lookupKey }
      }).promise();

      return {
        statusCode: 200,
        body: JSON.stringify(result.Item || {})
      };
    } else if (action === 'update') {
      // Authorization check for updates
      if (!checkAuthorization(sanitizedUsername, authenticatedUser)) {
        return { statusCode: 403, body: JSON.stringify({ error: 'not authorized' }) };
      }

      await dynamodb.update({
        TableName: process.env.USERS_TABLE || 'user-profiles',
        Key: { username_normalized: lookupKey },
        UpdateExpression: 'SET profile_data = :data, updated_at = :ts',
        ExpressionAttributeValues: {
          ':data': body.profile_data,
          ':ts': new Date().toISOString()
        }
      }).promise();

      return {
        statusCode: 200,
        body: JSON.stringify({ message: 'profile updated' })
      };
    }

    return { statusCode: 400, body: JSON.stringify({ error: 'invalid action' }) };
  } catch (err) {
    console.error('Error:', err);
    return { statusCode: 500, body: JSON.stringify({ error: 'internal error' }) };
  }
};
